<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">baseUrl = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.weather.com/v1&quot;</span></span>
